// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(amount < type(uint256).max / 2);
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 after = c.proposalCount();
        assertTrue(after == before + 1, "newGrantProposal must increment proposalCount");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount, address proposedAddress, string calldata typeStr) public {
        vm.assume(recipient != address(0));
        c.newGrantProposal(recipient, amount);
        uint256 grantID = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        uint256 addrID = c.proposalCount();
        assertTrue(addrID == grantID + 1 && c.mapPID_grant(grantID).recipient == recipient && c.mapPID_grant(grantID).amount == amount && !isEqualStr(c.mapPID_type(addrID), "GRANT"));
    }
    function isEqualStr(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        c.newGrantProposal(recipient, amount);
        assertTrue(
            keccak256(bytes(c.mapPID_type(c.proposalCount()))) == keccak256(bytes("GRANT")) &&
            keccak256(bytes(c.mapPID_type(0))) == keccak256(bytes("")) &&
            c.mapPID_grant(c.proposalCount()).amount == amount,
            "grant proposal must be stored at the new incremented proposal ID"
        );
    }
}
